class Solution {
public:
    vector<int> getOrder(vector<vector<int>>& tasks) {
        int n = tasks.size();
        vector<vector<long long>> indexed(n);
        for (int i = 0; i < n; ++i) {
            indexed[i] = {(long long)tasks[i][0], (long long)tasks[i][1], (long long)i};
        }
        sort(indexed.begin(), indexed.end());

        using P = pair<long long, int>;
        priority_queue<P, vector<P>, greater<P>> pq;
        vector<int> ans;
        ans.reserve(n);
        long long currTime = 0;
        int idx = 0;

        while (idx < n || !pq.empty()) {
            if (pq.empty() && currTime < indexed[idx][0]) {
                currTime = indexed[idx][0];
            }
            while (idx < n && indexed[idx][0] <= currTime) {
                pq.push({indexed[idx][1], (int)indexed[idx][2]});
                idx++;
            }
            auto [dur, origIdx] = pq.top();
            pq.pop();
            currTime += dur;
            ans.push_back(origIdx);
        }
        return ans;
    }
};

import java.util.*;

class Solution {
    public int[] getOrder(int[][] tasks) {
        int n = tasks.length;
        long[][] indexed = new long[n][3];
        for (int i = 0; i < n; ++i) {
            indexed[i] = new long[]{tasks[i][0], tasks[i][1], i};
        }
        Arrays.sort(indexed, (a, b) -> Long.compare(a[0], b[0]));

        PriorityQueue<long[]> pq = new PriorityQueue<>((a, b) -> {
            if (a[0] != b[0]) return Long.compare(a[0], b[0]);
            return Long.compare(a[1], b[1]);
        });

        int[] ans = new int[n];
        int ansIdx = 0;
        long currTime = 0;
        int idx = 0;

        while (idx < n || !pq.isEmpty()) {
            if (pq.isEmpty() && currTime < indexed[idx][0]) {
                currTime = indexed[idx][0];
            }
            while (idx < n && indexed[idx][0] <= currTime) {
                pq.offer(new long[]{indexed[idx][1], indexed[idx][2]});
                idx++;
            }
            long[] top = pq.poll();
            currTime += top[0];
            ans[ansIdx++] = (int)top[1];
        }
        return ans;
    }
}

/**
 * @param {number[][]} tasks
 * @return {number[]}
 */
var getOrder = function(tasks) {
    const n = tasks.length;
    const indexed = tasks.map((t, i) => [t[0], t[1], i]);
    indexed.sort((a, b) => a[0] - b[0]);

    const pq = [];
    const push = (item) => {
        pq.push(item);
        let idx = pq.length - 1;
        while (idx > 0) {
            const p = Math.floor((idx - 1) / 2);
            if (pq[p][0] > pq[idx][0] || (pq[p][0] === pq[idx][0] && pq[p][1] > pq[idx][1])) {
                [pq[p], pq[idx]] = [pq[idx], pq[p]];
                idx = p;
            } else break;
        }
    };

    const pop = () => {
        if (pq.length === 0) return null;
        const top = pq[0];
        const last = pq.pop();
        if (pq.length > 0) {
            pq[0] = last;
            let idx = 0;
            while (true) {
                let left = 2 * idx + 1, right = 2 * idx + 2, best = idx;
                if (left < pq.length && (pq[left][0] < pq[best][0] || (pq[left][0] === pq[best][0] && pq[left][1] < pq[best][1]))) best = left;
                if (right < pq.length && (pq[right][0] < pq[best][0] || (pq[right][0] === pq[best][0] && pq[right][1] < pq[best][1]))) best = right;
                if (best !== idx) {
                    [pq[idx], pq[best]] = [pq[best], pq[idx]];
                    idx = best;
                } else break;
            }
        }
        return top;
    };

    const ans = [];
    let currTime = 0;
    let idx = 0;

    while (idx < n || pq.length > 0) {
        if (pq.length === 0 && currTime < indexed[idx][0]) {
            currTime = indexed[idx][0];
        }
        while (idx < n && indexed[idx][0] <= currTime) {
            push([indexed[idx][1], indexed[idx][2]]);
            idx++;
        }
        const [dur, origIdx] = pop();
        currTime += dur;
        ans.push(origIdx);
    }
    return ans;
};
